import {createRingworld} from '../../src/terrain/ringworld.ts';
import {RingworldDisplayCache} from '../../src/editor/ringworld-document.ts';
import {openCylinderRasterSteps} from '../../src/rendering/open-cylinder-raster.ts';
import {OpenCylinderWebGLRenderer} from '../../src/rendering/open-cylinder-webgl.ts';
import {initialOpenCylinderView,openCylinderViewAdapter,type OpenCylinderView} from '../../src/rendering/open-cylinder-view.ts';
import {openCylinderElevationSampler,cylinderElevationColor,cylinderRelief} from '../../src/rendering/open-cylinder-elevation.ts';
const size={width:960,height:640};
export async function renderRingworld(n:128|256,scene:string){
 const world=createRingworld({terrainId:'terrain',geometry:{provider:'physical-rectangular-ringworld',version:1,identity:{worldId:'world',surfaceId:'boundary'},innerRadiusMeters:1e6,outerRadiusMeters:1.2e6,widthMeters:4e5},detail:n}),t=world.terrain,g=t.geometry,A=t.metadata.representation.resolution.angularSamples,S=g.meridianLengthMeters;
 for(let i=0;i<t.sampleCount;i++){const row=t.rowGeometry(Math.floor(i/A)),theta=i%A/A*2*Math.PI;t.write(t.keyAt(i),Math.fround(1600*Math.sin(3*theta+.2)+1000*Math.cos(row.meridian/S*2*Math.PI)-200));}
 const digest=async()=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',t.copyElevations().buffer)),x=>x.toString(16).padStart(2,'0')).join(''),before=await digest(),cache=new RingworldDisplayCache(world);for(const _ of cache.prepare()){void _;}
 let view:OpenCylinderView=initialOpenCylinderView(scene==='inner'?'interior':'exterior',scene.includes('map')?'map':'physical');
 if(scene==='top')view={...view,frame:{right:[1,0,0],up:[0,1,0],forward:[0,0,1]}};
 if(scene==='bottom')view={...view,frame:{right:[1,0,0],up:[0,-1,0],forward:[0,0,-1]}};
 if(scene==='zoom')view={...view,zoom:2.5,target:[.6,-.25,0]};
 if(scene==='inner-map')view={...view,scope:'interior',interior:true,zoom:4,pan:{x:0,y:(S/2-(1.5*4e5+2e5))/1.2e6}};
 if(scene==='seam-map')view={...view,phase:Math.PI,zoom:2};
 const adapter=openCylinderViewAdapter(g,view,size),l=adapter.layout,job=openCylinderRasterSteps(cache,view,size,size.width*size.height,undefined,'relief');let step=job.next();while(!step.done)step=job.next();const image=step.value,cpu=document.createElement('canvas'),gpu=document.createElement('canvas');cpu.width=image.columns;cpu.height=image.rows;cpu.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(image.pixels),image.columns,image.rows),0,0);
 const renderer=new OpenCylinderWebGLRenderer(gpu,cache,()=>{});await renderer.whenReady();renderer.present(view,size,'relief');const gl=gpu.getContext('webgl2')!,raw=new Uint8Array(gpu.width*gpu.height*4);gl.readPixels(0,0,gpu.width,gpu.height,gl.RGBA,gl.UNSIGNED_BYTE,raw);const data=cpu.getContext('2d')!.getImageData(0,0,cpu.width,cpu.height).data,field=openCylinderElevationSampler(t.copyElevations(),t,'land');
 // Independent analytic annular solid: intersect both nested cylinders and
 // the two axial planes, then choose the nearest real boundary. This does not
 // call the production ray, excavation interval or visibility implementation.
 const dot=(a:readonly number[],b:readonly number[])=>a.reduce((s,x,i)=>s+x*b[i]!,0),reference=(x:number,y:number)=>{
  const px=(x-l.x)/l.scale,py=(l.y-y)/l.scale;
  if(view.mode==='map'){const angle=px-view.pan.x,m=S/2+(py-view.pan.y)*1.2e6;if(Math.abs(angle)>Math.PI||m<0||m>S)return;const patchId=m<=4e5?'outer-wall':m<=6e5?'rim-end':m<=1e6?'inner-wall':'rim-start';return{patchId,theta:view.phase+angle,radiusMeters:patchId==='outer-wall'?1.2e6:patchId==='inner-wall'?1e6:patchId==='rim-end'?1.2e6-(m-4e5):1e6+(m-1e6),zMeters:patchId==='outer-wall'?m:patchId==='inner-wall'?1e6-m:patchId==='rim-end'?4e5:0,facing:1};}
  const R=view.scope==='interior'?1e6:1.2e6,h=4e5/R/2,ratio=1e6/1.2e6,f=view.frame,tx=dot(view.target,f.right),ty=dot(view.target,f.up),o=f.right.map((v,i)=>v*(px+tx)+f.up[i]!*(py+ty)+f.forward[i]!*4),d=f.forward.map(v=>-v),hits:{distance:number;point:number[];patchId:string;normal:number[]}[]=[];
  for(const radius of[1,ratio]){const aa=d[0]!**2+d[1]!**2,bb=2*(o[0]!*d[0]!+o[1]!*d[1]!),cc=o[0]!**2+o[1]!**2-radius*radius,disc=bb*bb-4*aa*cc;if(aa>1e-24&&disc>=0)for(const distance of[(-bb-Math.sqrt(disc))/(2*aa),(-bb+Math.sqrt(disc))/(2*aa)]){const p=o.map((v,i)=>v+d[i]!*distance);if(distance>0&&Math.abs(p[2]!)<=h){const outer=radius===1,sign=outer?1:-1;hits.push({distance,point:p,patchId:outer?'outer-wall':'inner-wall',normal:[sign*p[0]!/radius,sign*p[1]!/radius,0]});}}}
  if(Math.abs(d[2]!)>1e-14)for(const z of[-h,h]){const distance=(z-o[2]!)/d[2]!,p=o.map((v,i)=>v+d[i]!*distance),rho=Math.hypot(p[0]!,p[1]!);if(distance>0&&rho>=ratio&&rho<=1)hits.push({distance,point:p,patchId:z>0?'rim-end':'rim-start',normal:[0,0,z>0?1:-1]});}
  hits.sort((a,b)=>a.distance-b.distance);const hit=hits[0];if(!hit)return;const inside=view.scope==='interior',rho=Math.hypot(hit.point[0]!,hit.point[1]!);return{patchId:inside&&hit.patchId.endsWith('wall')?hit.patchId==='outer-wall'?'inner-wall':'outer-wall':hit.patchId,theta:Math.atan2(hit.point[1]!,hit.point[0]!),radiusMeters:inside?1e6/rho:rho*1.2e6,zMeters:Math.max(0,Math.min(4e5,hit.point[2]!*R+2e5)),facing:.74+.26*Math.max(0,dot(hit.normal,f.forward))};
 };
 let stableChecked=0,stableMax=0,envelopeViolations=0,envelopeMax=0,referenceMax=0,geometryViolations=0,empty=0,coasts=0,land=0,ocean=0,edgeChecked=0,coverageMax=0,gpuEdgeEnvelopeViolations=0;const regions:Record<string,number>={},worst:unknown[]=[];let stableWorst:unknown;
 for(let y=3;y<size.height-3;y+=2)for(let x=3;x<size.width-3;x+=2){const at=(y*size.width+x)*4,ga=((size.height-1-y)*size.width+x)*4,p=reference(x+.5,y+.5),around=[[-2,0],[2,0],[0,-2],[0,2]].map(([dx,dy])=>reference(x+.5+dx!,y+.5+dy!));if(!p&&around.every(q=>!q)){empty++;if(data[at+3]||raw[ga+3])geometryViolations++;continue;}if(!p||around.some(q=>!q)){edgeChecked++;const coverage=(xx:number,yy:number)=>Math.round([[-.25,-.25],[-.25,.25],[.25,-.25],[.25,.25]].filter(([dx,dy])=>reference(xx+.5+dx!,yy+.5+dy!)).length/4*255),expected=coverage(x,y);coverageMax=Math.max(coverageMax,Math.abs(data[at+3]!-expected));const envelope=[[-2,0],[2,0],[0,-2],[0,2],[0,0]].map(([dx,dy])=>coverage(x+dx!,y+dy!));if(raw[ga+3]!<Math.min(...envelope)-3||raw[ga+3]!>Math.max(...envelope)+3)gpuEdgeEnvelopeViolations++;continue;}
  if(data[at+3]!==255||raw[ga+3]!==255){geometryViolations++;continue;}regions[p.patchId]=(regions[p.patchId]??0)+1;
  let variation=0,difference=0,bad=false;for(let c=0;c<4;c++){let low=Infinity,high=-Infinity;for(const dy of[-2,0,2])for(const dx of[-2,0,2]){const k=((y+dy)*size.width+x+dx)*4,value=c===3?data[k+3]!:data[k+c]!*data[k+3]!/255;low=Math.min(low,value);high=Math.max(high,value);}variation=Math.max(variation,high-low);const error=Math.max(low-raw[ga+c]!,raw[ga+c]!-high,0);envelopeMax=Math.max(envelopeMax,error);bad||=error>3;difference=Math.max(difference,Math.abs(data[at+c]!-raw[ga+c]!));}if(bad){envelopeViolations++;if(worst.length<8)worst.push({x,y,p,cpu:[...data.slice(at,at+4)],gpu:[...raw.slice(ga,ga+4)]});}
  const sample=field(p as Parameters<typeof field>[0]);if(sample.crossesSea)coasts++;if(sample.height>0)land++;else ocean++;
  if(variation<=12&&!sample.crossesSea&&around.every(q=>q!.patchId===p.patchId&&!field(q as Parameters<typeof field>[0]).crossesSea)){stableChecked++;if(difference>stableMax)stableWorst={x,y,p,sample,variation,cpu:[...data.slice(at,at+4)],gpu:[...raw.slice(ga,ga+4)]};stableMax=Math.max(stableMax,difference);const color=cylinderElevationColor(sample.height,0),shade=p.facing*(sample.height>0?cylinderRelief(sample.dx,sample.dy):1);referenceMax=Math.max(referenceMax,...[0,1,2].map(c=>Math.abs(Math.round(color[c]!*shade)-data[at+c]!)));}
 }

 const result={n,scene,before,after:await digest(),stableChecked,stableMax,envelopeMax,envelopeViolations,referenceMax,geometryViolations,empty,coasts,land,ocean,edgeChecked,coverageMax,gpuEdgeEnvelopeViolations,regions,worst,stableWorst,graphics:{...renderer.statistics},cacheBytes:cache.byteLength,authorityBytes:t.elevationByteLength};
 document.querySelector('#root')?.setAttribute('style','display:none');document.body.style.cssText='background:#102b3a;color:white;margin:12px';const label=document.createElement('p');label.textContent=`Ringworld N${n} ${scene} — Canvas / WebGL2, identical canonical words and camera`;document.body.append(label);for(const canvas of[cpu,gpu]){canvas.style.cssText='width:700px;height:467px;display:inline-block';document.body.append(canvas);}return result;
}
